3	import java.time.LocalDate;
4	import java.time.OffsetDateTime;
5	import java.util.List;
6	import java.util.Map;
7	import org.springframework.context.annotation.Profile;
8	import org.springframework.jdbc.core.JdbcTemplate;
9	import org.springframework.web.bind.annotation.PostMapping;
10	import org.springframework.web.bind.annotation.RequestBody;
11	import org.springframework.web.bind.annotation.RequestMapping;
12	import org.springframework.web.bind.annotation.RestController;
13	
14	/**
15	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
16	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
17	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
18	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
19	 */
20	@Profile("harness")
21	@RestController
22	@RequestMapping("/__test__")
23	public class TestSupportController {
24	
25	    private final Audit audit;
26	    private final JdbcTemplate jdbc;
27	
28	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
29	        this.audit = audit;
30	        this.jdbc = jdbc;
31	    }
32	
33	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
34	    @PostMapping("/reset")
35	    public void reset() {
36	        audit.clear();
37	        // Disable FK checks so a referenced parent (clients) can be truncated alongside its child.
38	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
39	        jdbc.execute("TRUNCATE TABLE payments RESTART IDENTITY");
40	        jdbc.execute("TRUNCATE TABLE line_items RESTART IDENTITY");
41	        jdbc.execute("TRUNCATE TABLE invoices RESTART IDENTITY");
42	        jdbc.execute("TRUNCATE TABLE contacts RESTART IDENTITY");
43	        jdbc.execute("TRUNCATE TABLE tasks RESTART IDENTITY");
44	        jdbc.execute("TRUNCATE TABLE notes RESTART IDENTITY");
45	        jdbc.execute("TRUNCATE TABLE project_tags RESTART IDENTITY");
46	        jdbc.execute("TRUNCATE TABLE tags RESTART IDENTITY");
47	        jdbc.execute("TRUNCATE TABLE projects RESTART IDENTITY");
48	        jdbc.execute("TRUNCATE TABLE clients RESTART IDENTITY");
49	        jdbc.execute("TRUNCATE TABLE dashboard_settings");
50	        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
51	    }
52	
53	    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
54	    @PostMapping("/seed")
55	    @SuppressWarnings("unchecked")
56	    public void seed(@RequestBody Map<String, Object> fixture) {
57	        // The dashboard measures invoice "overdue" against a fixed reference date; store it when the
58	        // fixture supplies one so the home-screen count is deterministic.
59	        Object asOf = fixture.get("asOf");
60	        if (asOf != null) {
61	            jdbc.update("INSERT INTO dashboard_settings (id, as_of) VALUES (1, ?)", asOf.toString());
62	        }
63	
64	        List<Map<String, Object>> clients =
65	                (List<Map<String, Object>>) fixture.getOrDefault("clients", List.of());
66	        long maxClientId = 0;
67	        for (Map<String, Object> client : clients) {
68	            long id = ((Number) client.get("id")).longValue();
69	            // Seed with the fixture's explicit id (JdbcTemplate, not JPA) so specs can assert by id.
70	            jdbc.update("INSERT INTO clients (id, name, email) VALUES (?, ?, ?)",
71	                    id, client.get("name"), client.get("email"));
72	            maxClientId = Math.max(maxClientId, id);
73	        }
74	        if (maxClientId > 0) {
75	            // Advance the identity so app-generated ids don't collide with seeded rows.
76	            jdbc.execute("ALTER TABLE clients ALTER COLUMN id RESTART WITH " + (maxClientId + 1));
77	        }
78	
79	        List<Map<String, Object>> projects =
80	                (List<Map<String, Object>>) fixture.getOrDefault("projects", List.of());
81	        long maxProjectId = 0;
82	        for (Map<String, Object> project : projects) {
83	            long id = ((Number) project.get("id")).longValue();
84	            long clientId = ((Number) project.get("clientId")).longValue();
85	            String status = (String) project.getOrDefault("status", "ACTIVE");
86	            boolean archived = Boolean.TRUE.equals(project.getOrDefault("archived", Boolean.FALSE));
87	            double budget = ((Number) project.getOrDefault("budget", 0)).doubleValue();
88	            jdbc.update(
89	                    "INSERT INTO projects (id, name, client_id, status, archived, budget) VALUES (?, ?, ?, ?, ?, ?)",
90	                    id, project.get("name"), clientId, status, archived, budget);
91	            maxProjectId = Math.max(maxProjectId, id);
92	        }
93	        if (maxProjectId > 0) {
94	            jdbc.execute("ALTER TABLE projects ALTER COLUMN id RESTART WITH " + (maxProjectId + 1));
95	        }
96	
97	        List<Map<String, Object>> contacts =
98	                (List<Map<String, Object>>) fixture.getOrDefault("contacts", List.of());
99	        long maxContactId = 0;
100	        for (Map<String, Object> contact : contacts) {
101	            long id = ((Number) contact.get("id")).longValue();
102	            long clientId = ((Number) contact.get("clientId")).longValue();
103	            jdbc.update("INSERT INTO contacts (id, client_id, name, email, role) VALUES (?, ?, ?, ?, ?)",
104	                    id, clientId, contact.get("name"), contact.get("email"), contact.get("role"));
105	            maxContactId = Math.max(maxContactId, id);
106	        }
107	        if (maxContactId > 0) {
108	            jdbc.execute("ALTER TABLE contacts ALTER COLUMN id RESTART WITH " + (maxContactId + 1));
109	        }
110	
111	        List<Map<String, Object>> tasks =
112	                (List<Map<String, Object>>) fixture.getOrDefault("tasks", List.of());
113	        long maxTaskId = 0;
114	        for (Map<String, Object> task : tasks) {
115	            long id = ((Number) task.get("id")).longValue();
116	            long projectId = ((Number) task.get("projectId")).longValue();
117	            boolean done = Boolean.TRUE.equals(task.getOrDefault("done", Boolean.FALSE));
118	            jdbc.update("INSERT INTO tasks (id, project_id, title, done) VALUES (?, ?, ?, ?)",
119	                    id, projectId, task.get("title"), done);
120	            maxTaskId = Math.max(maxTaskId, id);
121	        }
122	        if (maxTaskId > 0) {
123	            jdbc.execute("ALTER TABLE tasks ALTER COLUMN id RESTART WITH " + (maxTaskId + 1));
124	        }
125	
126	        List<Map<String, Object>> tags =
127	                (List<Map<String, Object>>) fixture.getOrDefault("tags", List.of());
128	        long maxTagId = 0;
129	        for (Map<String, Object> tag : tags) {
130	            long id = ((Number) tag.get("id")).longValue();
131	            jdbc.update("INSERT INTO tags (id, name) VALUES (?, ?)", id, tag.get("name"));
132	            maxTagId = Math.max(maxTagId, id);
133	        }
134	        if (maxTagId > 0) {
135	            jdbc.execute("ALTER TABLE tags ALTER COLUMN id RESTART WITH " + (maxTagId + 1));
136	        }
137	
138	        List<Map<String, Object>> projectTags =
139	                (List<Map<String, Object>>) fixture.getOrDefault("projectTags", List.of());
140	        for (Map<String, Object> projectTag : projectTags) {
141	            long projectId = ((Number) projectTag.get("projectId")).longValue();
142	            long tagId = ((Number) projectTag.get("tagId")).longValue();
143	            jdbc.update("INSERT INTO project_tags (project_id, tag_id) VALUES (?, ?)",
144	                    projectId, tagId);
145	        }
146	
147	        List<Map<String, Object>> notes =
148	                (List<Map<String, Object>>) fixture.getOrDefault("notes", List.of());
149	        long maxNoteId = 0;
150	        for (Map<String, Object> note : notes) {
151	            long id = ((Number) note.get("id")).longValue();
152	            long targetId = ((Number) note.get("targetId")).longValue();
153	            jdbc.update(
154	                    "INSERT INTO notes (id, target_type, target_id, text, at) VALUES (?, ?, ?, ?, ?)",
155	                    id, note.get("targetType"), targetId, note.get("text"),
156	                    OffsetDateTime.parse((String) note.get("at")));
157	            maxNoteId = Math.max(maxNoteId, id);
158	        }
159	        if (maxNoteId > 0) {
160	            jdbc.execute("ALTER TABLE notes ALTER COLUMN id RESTART WITH " + (maxNoteId + 1));
161	        }
162	
163	        List<Map<String, Object>> invoices =
164	                (List<Map<String, Object>>) fixture.getOrDefault("invoices", List.of());
165	        long maxInvoiceId = 0;
166	        long maxLineItemId = 0;
167	        for (Map<String, Object> invoice : invoices) {
168	            long id = ((Number) invoice.get("id")).longValue();
169	            long projectId = ((Number) invoice.get("projectId")).longValue();
170	            // An invoice is itemised: its amount is derived as the sum of each line's qty * price.
171	            // A fixture may still pass an explicit amount for a line-item-less invoice.
172	            List<Map<String, Object>> lineItems =
173	                    (List<Map<String, Object>>) invoice.getOrDefault("lineItems", List.of());
174	            double amount = lineItems.isEmpty() && invoice.get("amount") != null
